def odd_Equivalent(s, n):
    """Write a python function to find the count of rotations of a binary string with odd value."""
    if not s or n is None or n <= 0:
        return 0
    # A binary number is odd iff its last bit is 1. In the n rotations
    # of the string, each character becomes the last bit exactly once,
    # so the number of odd rotations equals the number of '1's in the
    # (length-n) string.
    return s[:n].count("1")
